const enc=new TextEncoder();
export const products={undos:{title:'Second chances',description:'5 undos for Orbit Merge',price:25,quantity:5},shuffles:{title:'Cosmic Shuffle',description:'3 shuffles for Orbit Merge',price:25,quantity:3},rescues:{title:'Room to breathe',description:'3 rescues for Orbit Merge',price:50,quantity:3}};
const json=(data,status=200)=>new Response(JSON.stringify(data),{status,headers:{'content-type':'application/json','cache-control':'no-store','x-content-type-options':'nosniff'}});
async function hmac(key,text){const k=await crypto.subtle.importKey('raw',typeof key==='string'?enc.encode(key):key,{name:'HMAC',hash:'SHA-256'},false,['sign']);return new Uint8Array(await crypto.subtle.sign('HMAC',k,enc.encode(text)));}
function equal(a,b){if(a.length!==b.length)return false;let n=0;for(let i=0;i<a.length;i++)n|=a.charCodeAt(i)^b.charCodeAt(i);return n===0;}
export async function identity(raw,token,now=Date.now()){
 if(!raw||!token)throw new Error('Open the game inside Telegram to use purchases.');
 const p=new URLSearchParams(raw),hash=p.get('hash');if(!hash||!/^[a-f0-9]{64}$/.test(hash)||new Set(p.keys()).size!==[...p.keys()].length)throw new Error('Invalid Telegram authentication.');p.delete('hash');
 const text=[...p.entries()].sort(([a],[b])=>a<b?-1:a>b?1:0).map(([k,v])=>`${k}=${v}`).join('\n');
 const secret=await hmac('WebAppData',token),digest=await hmac(secret,text),expected=[...digest].map(b=>b.toString(16).padStart(2,'0')).join('');if(!equal(hash,expected))throw new Error('Invalid Telegram authentication.');
 const age=Math.floor(now/1000)-Number(p.get('auth_date'));if(!Number.isFinite(age)||age< -30||age>3600)throw new Error('Telegram session expired. Reopen the game.');const u=JSON.parse(p.get('user')||'null');if(!Number.isSafeInteger(u?.id)||u.id<=0)throw new Error('Invalid Telegram user.');return u;
}
export async function balance(db,id){await db.prepare('INSERT OR IGNORE INTO accounts(user_id) VALUES(?)').bind(id).run();return db.prepare('SELECT undos,rescues FROM accounts WHERE user_id=?').bind(id).first();}
export async function settle(db,p,user){
 const o=await db.prepare('SELECT * FROM orders WHERE id=?').bind(p.invoice_payload).first();if(!o||o.user_id!==user||p.currency!=='XTR'||p.total_amount!==o.amount||typeof p.telegram_payment_charge_id!=='string')throw new Error('Payment does not match an order.');
 if(o.paid){if(o.charge!==p.telegram_payment_charge_id)throw new Error('Conflicting payment.');return false;}
 const product=products[o.product];if(!product)throw new Error('Invalid product.');
 // D1 batch is transactional: a duplicate charge rolls back the inventory update.
 await db.batch([
 db.prepare('INSERT OR IGNORE INTO accounts(user_id) VALUES(?)').bind(user),
 db.prepare(`UPDATE accounts SET ${o.product}=${o.product}+? WHERE user_id=? AND EXISTS(SELECT 1 FROM orders WHERE id=? AND paid=0)`).bind(product.quantity,user,o.id),
 db.prepare('UPDATE orders SET paid=1,charge=? WHERE id=? AND paid=0').bind(p.telegram_payment_charge_id,o.id)
 ]);return true;
}
export async function consume(db,user,kind,key){
 if(!Object.hasOwn(products,kind)||typeof key!=='string'||!/^[a-f0-9-]{36}$/.test(key))throw new Error('Invalid booster action.');
 await db.batch([
 db.prepare(`INSERT OR IGNORE INTO consumptions(id,user_id,kind,applied) SELECT ?,?,?,0 WHERE EXISTS(SELECT 1 FROM accounts WHERE user_id=? AND ${kind}>0)`).bind(key,user,kind,user),
 db.prepare(`UPDATE accounts SET ${kind}=${kind}-1 WHERE user_id=? AND ${kind}>0 AND EXISTS(SELECT 1 FROM consumptions WHERE id=? AND user_id=? AND kind=? AND applied=0)`).bind(user,key,user,kind),
 db.prepare('UPDATE consumptions SET applied=1 WHERE id=? AND user_id=? AND kind=? AND applied=0').bind(key,user,kind)
 ]);
 const action=await db.prepare('SELECT * FROM consumptions WHERE id=?').bind(key).first();if(!action)throw new Error('No boosters left. Find optional boosters in the shop.');if(action.user_id!==user||action.kind!==kind)throw new Error('Action conflict.');return balance(db,user);
}
async function bot(env,method,data){const r=await fetch(`https://api.telegram.org/bot${env.TELEGRAM_BOT_TOKEN}/${method}`,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(data),signal:AbortSignal.timeout(8000)});const body=await r.json();if(!r.ok||!body.ok)throw new Error('Telegram service unavailable. Please try again.');return body.result;}
async function body(req){const text=await req.text();if(text.length>24000)throw new Error('Request too large.');return text?JSON.parse(text):{};}
function configured(env){return !!(env.DB&&env.TELEGRAM_BOT_TOKEN&&env.TELEGRAM_WEBHOOK_SECRET&&/^https:\/\//.test(env.PUBLIC_ORIGIN||'')&&/^\d+$/.test(env.OWNER_CHAT_ID||''));}
const requests=new Map();function throttle(user){const now=Date.now(),old=requests.get(user)||{at:now,n:0};if(now-old.at>60000){old.at=now;old.n=0;}if(++old.n>30)throw new Error('Too many requests. Wait a minute.');requests.set(user,old);if(requests.size>5000)for(const [k,v] of requests)if(now-v.at>60000)requests.delete(k);}
export function makeWorker(assets){return {async fetch(req,env){const url=new URL(req.url),ready=configured(env),live=ready&&env.PAYMENTS_ENABLED==='true';try{
 const monetag=env.ADS_ENABLED==='true'&&env.AD_PROVIDER==='monetag'&&/^\d+$/.test(env.MONETAG_ZONE||'')&&/^https:\/\//.test(env.MONETAG_SDK_URL||'') ? {zone:env.MONETAG_ZONE,scriptUrl:env.MONETAG_SDK_URL} : null;
 if(req.method==='GET'&&url.pathname==='/api/config')return json({payments:live,botUsername:'OrbitMergeAjayBot',monetag,ads:env.AD_PROVIDER!=='monetag'&&env.ADS_ENABLED==='true'&&/^\d+$/.test(env.ADSGRAM_BLOCK_ID||''),adsBlockId:env.ADS_ENABLED==='true'?env.ADSGRAM_BLOCK_ID:null});
 if(req.method==='GET'&&url.pathname==='/health')return json({ok:true,storage:!!env.DB,paymentsConfigured:ready,paymentsEnabled:live});
 if(url.pathname==='/telegram/webhook'&&req.method==='POST'){
 if(!ready||!equal(req.headers.get('x-telegram-bot-api-secret-token')||'',env.TELEGRAM_WEBHOOK_SECRET))return json({error:'Forbidden'},403);
 const update=await body(req),q=update.pre_checkout_query,m=update.message;
 if(q){const o=await env.DB.prepare('SELECT * FROM orders WHERE id=?').bind(q.invoice_payload).first();const ok=!!(live&&o&&!o.paid&&o.user_id===q.from.id&&q.currency==='XTR'&&q.total_amount===o.amount);await bot(env,'answerPreCheckoutQuery',{pre_checkout_query_id:q.id,ok,...(!ok?{error_message:'This order is unavailable. Please open a new invoice.'}:{})});}
 if(m?.successful_payment)await settle(env.DB,m.successful_payment,m.from.id);
 if(m?.text?.startsWith('/start'))await bot(env,'sendMessage',{chat_id:m.chat.id,text:'Welcome to Orbit Merge! New games are always free.',reply_markup:{inline_keyboard:[[{text:'Play Orbit Merge',web_app:{url:env.PUBLIC_ORIGIN}}]]}});
 if(m?.text&&String(m.from.id)===env.OWNER_CHAT_ID&&m.chat.type==='private'){
 if(m.text==='/tickets'){const result=await env.DB.prepare('SELECT id,user_id,body FROM support_tickets ORDER BY id DESC LIMIT 10').all();await bot(env,'sendMessage',{chat_id:m.chat.id,text:result.results.length?result.results.map(t=>`#${t.id} · user ${t.user_id}\n${t.body}`).join('\n\n').slice(0,3900):'No payment support requests yet.'});}
 const reply=m.text.match(/^\/reply\s+(\d+)\s+([\s\S]{1,2000})$/);if(reply){const ticket=await env.DB.prepare('SELECT user_id FROM support_tickets WHERE id=?').bind(Number(reply[1])).first();if(ticket){await bot(env,'sendMessage',{chat_id:ticket.user_id,text:`Orbit Merge support #${reply[1]}\n${reply[2]}`});await bot(env,'sendMessage',{chat_id:m.chat.id,text:`Reply sent for ticket #${reply[1]}.`});}else await bot(env,'sendMessage',{chat_id:m.chat.id,text:'Ticket not found.'});}
 }
 if(m?.text?.startsWith('/paysupport')){
 const result=await env.DB.prepare('INSERT OR IGNORE INTO support_tickets(update_id,user_id,body,created) VALUES(?,?,?,?) RETURNING id').bind(update.update_id,m.from.id,m.text.slice(0,2000),Date.now()).first();
 if(result){await bot(env,'sendMessage',{chat_id:env.OWNER_CHAT_ID,text:`Orbit Merge payment support #${result.id}\nTelegram user: ${m.from.id}\n${m.text.slice(0,2000)}\nReply with /reply ${result.id} YOUR ANSWER. Use /tickets to review recent requests. Review the receipt before any refund.`});}
 await bot(env,'sendMessage',{chat_id:m.chat.id,text:'Your payment support request is recorded. Send /paysupport followed by the purchase date, issue and Telegram receipt reference. Never send passwords or login codes. The game owner will review it.'});}
 if(m?.text?.startsWith('/privacy'))await bot(env,'sendMessage',{chat_id:m.chat.id,text:'Practice progress stays on your device. We store Telegram IDs, order/payment IDs, paid balances and support requests to deliver purchases. Use /paysupport for data requests. Optional rewarded ads use AdsGram only when you choose to watch.'});
 return json({ok:true});}
 if(url.pathname.startsWith('/api/')){
 if(req.method!=='POST')return json({error:'Method not allowed'},405);if(!ready)return json({error:'Purchases are not available yet. Enjoy free play.'},503);if(req.headers.get('origin')&&req.headers.get('origin')!==env.PUBLIC_ORIGIN)return json({error:'Origin not allowed'},403);
 const user=await identity(req.headers.get('x-telegram-init-data'),env.TELEGRAM_BOT_TOKEN);throttle(user.id);const data=await body(req);
 if(url.pathname==='/api/account')return json(await balance(env.DB,user.id));
 if(url.pathname==='/api/order'){
  if(typeof data.orderId!=='string'||data.orderId.length!==36)return json({error:'Invalid order reference.'},400);
  const purchase=await env.DB.prepare('SELECT paid FROM orders WHERE id=? AND user_id=?').bind(data.orderId,user.id).first();
  if(!purchase)return json({error:'Order not found.'},404);
  return json({paid:purchase.paid===1});
 }
 if(url.pathname==='/api/consume')return json(await consume(env.DB,user.id,data.kind,data.request_id));
 if(url.pathname==='/api/invoice'){
 if(!live)return json({error:'Purchases are not enabled yet.'},503);const p=Object.hasOwn(products,data.product)?products[data.product]:null;if(!p)throw new Error('Unknown booster.');const key=crypto.randomUUID();await env.DB.prepare('INSERT INTO orders(id,user_id,product,amount,created) VALUES(?,?,?,?,?)').bind(key,user.id,data.product,p.price,Date.now()).run();
 const link=await bot(env,'createInvoiceLink',{title:p.title,description:p.description,payload:key,provider_token:'',currency:'XTR',prices:[{label:p.title,amount:p.price}]});return json({url:link,orderId:key});}
 return json({error:'Not found'},404);}
 const asset=assets[url.pathname==='/'?'/index.html':url.pathname];if(!asset)return json({error:'Not found'},404);if(!['GET','HEAD'].includes(req.method))return json({error:'Method not allowed'},405);
 return new Response(req.method==='HEAD'?null:asset.body,{headers:{'content-type':asset.type,'cache-control':'no-cache','x-content-type-options':'nosniff','referrer-policy':'strict-origin-when-cross-origin'}});
 }catch(e){if(url.pathname==='/telegram/webhook')return json({error:'Processing failed; retry delivery.'},500);return json({error:e.message},400);}}};}

export default makeWorker({"/index.html":{"body":"<!doctype html><html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1,viewport-fit=cover\"><meta name=\"theme-color\" content=\"#f3f6fc\"><meta name=\"description\" content=\"Drop planets. Find a match. Make a bigger universe. A free merge puzzle built for Telegram.\"><title>Orbit Merge · A little space to play</title><link rel=\"stylesheet\" href=\"./style.css\"><script src=\"https://telegram.org/js/telegram-web-app.js\" defer></script></head><body>\n<aside class=\"intro\"><span class=\"orbit-mark\" aria-hidden=\"true\">◉</span><h1>A little space<br>to play.</h1><p>One drop. One clever match.<br>A bigger little universe.</p><div class=\"rule\"><span>1</span><p>Pick a lane.<br><strong>Your planet drops to the bottom.</strong></p></div><div class=\"rule\"><span>2</span><p>Find its twin.<br><strong>Touching matches become one.</strong></p></div><div class=\"rule\"><span>3</span><p>Keep some space.<br><strong>Chain merges. Beat your best.</strong></p></div><p class=\"aside-note\">No wallets. No waiting for energy.<br>Just one more good move.</p></aside>\n<main class=\"app\"><header><div class=\"brand\"><span aria-hidden=\"true\">◉</span><div>Orbit Merge<small>A bigger universe, one match at a time.</small></div></div><div class=\"header-actions\"><button class=\"icon\" id=\"sound\" aria-label=\"Toggle audio\">🔊</button><button class=\"icon\" id=\"help\" aria-label=\"How to play\">?</button></div></header>\n<nav aria-label=\"Game sections\"><button class=\"tab selected\" data-view=\"play\" aria-current=\"page\">Play</button><button class=\"tab\" data-view=\"shop\">Boosters</button><button class=\"tab\" data-view=\"records\">My orbit</button></nav>\n<section id=\"play\" class=\"view\"><div class=\"scoreline\"><div><span class=\"label\">SCORE</span><strong id=\"score\">0</strong></div><div class=\"best\"><span class=\"label\">PERSONAL BEST</span><strong id=\"best\">0</strong></div></div>\n<div class=\"mission\"><span aria-hidden=\"true\">✦</span><div id=\"mission\">Mission 1: Discover a 32 Planet</div><span id=\"progress\">0 / 32</span></div>\n<div class=\"game-wrap\"><div class=\"queue\"><span>Dropping next</span><span class=\"planet l1\" id=\"next\">2</span><span class=\"following\">then</span><span class=\"planet l2 small\" id=\"after\">4</span><span class=\"free-label\" id=\"mode\">FREE PLAY</span></div><div id=\"board\" class=\"board\" aria-label=\"Five-lane planet board\"></div><div class=\"lane-buttons\" id=\"lanes\" aria-label=\"Choose a lane\"></div><p class=\"board-tip\" id=\"tip\">Tap a lane or cell to drop. Match touching planets.</p></div>\n<div class=\"tools\"><button class=\"secondary\" id=\"daily\" type=\"button\">Daily challenge</button><button class=\"secondary\" id=\"daily-share\" type=\"button\" hidden>Share score</button></div><p id=\"daily-info\" class=\"muted\"></p><div class=\"tools\"><button class=\"secondary\" id=\"undo\">↶ Undo <span id=\"undo-count\">1 free</span></button><button class=\"secondary\" id=\"shuffle\">🔀 Shuffle <span id=\"shuffle-count\">1 free</span></button><button class=\"secondary\" id=\"new\">↻ New orbit</button></div><div class=\"status\" id=\"status\" role=\"status\" aria-live=\"polite\"></div><div id=\"gameover\" hidden class=\"over\"><h2>Your orbit is full.</h2><p id=\"over-copy\">A new universe is always free.</p><button class=\"primary\" id=\"restart\">Play again</button><button class=\"secondary\" id=\"rescue\">Use a rescue</button><button class=\"secondary\" id=\"ad\" disabled>Rewarded ad unavailable</button></div>\n<div class=\"collection\"><div><strong>Your next discovery</strong><span>Merge your way from dust to a star.</span></div><div class=\"discovery\"><span class=\"planet l3\">8</span><span class=\"connector\">→</span><span class=\"planet l4\">16</span><span class=\"connector\">→</span><span class=\"planet l5\">32</span></div></div></section>\n<section id=\"shop\" class=\"view\" hidden><h2>A little help, when you want it.</h2><p class=\"muted\">Play as much as you like for free. Boosters are optional, one-time purchases.</p><div id=\"commerce-status\" class=\"notice\">Open Orbit Merge in Telegram to buy boosters.</div>\n<article class=\"product\"><span class=\"product-symbol\">🎁</span><div><h3>Daily Orbit Supply<span class=\"badge deal\">Free Daily</span></h3><p id=\"daily-supply-desc\">Claim 1 free mystery booster every day.</p></div><button class=\"buy secondary\" id=\"daily-supply-btn\">Claim</button></article>\n<article class=\"product\"><span class=\"product-symbol\">↶</span><div><h3>Undo Pack</h3><p>5 undos. Take back your last drop.</p></div><button class=\"buy primary\" data-product=\"undos\" disabled>25 ★</button></article>\n<article class=\"product\"><span class=\"product-symbol\">🔀</span><div><h3>Cosmic Shuffle Pack</h3><p>3 shuffles. Rearrange crowded planets.</p></div><button class=\"buy primary\" data-product=\"shuffles\" disabled>25 ★</button></article>\n<article class=\"product\"><span class=\"product-symbol\">✦</span><div><h3>Rescue Pack</h3><p>3 rescues. Clear the top row of a full board.</p></div><button class=\"buy primary\" data-product=\"rescues\" disabled>50 ★</button></article>\n<p class=\"muted\" id=\"balance\">Paid boosters are stored with your Telegram account.</p><p class=\"fine\">Prices are in Telegram Stars. No recurring charges. Purchases require Telegram. For payment help, use <a href=\"https://t.me/OrbitMergeAjayBot\">the game bot</a> and send /paysupport.</p><button class=\"secondary\" id=\"check-purchase\" type=\"button\">Check purchase status</button><div class=\"status\" id=\"shop-status\" role=\"status\"></div></section>\n<section id=\"records\" class=\"view\" hidden><h2>Your little universe.</h2><p class=\"muted\">Personal records and achievements on this device.</p>\n<div class=\"record\"><span>Visual Theme</span><div class=\"theme-select\"><button class=\"theme-btn active\" data-set-theme=\"default\">Nebula</button><button class=\"theme-btn\" data-set-theme=\"cyber\">Cyber</button><button class=\"theme-btn\" data-set-theme=\"solar\">Solar</button></div></div>\n<div class=\"record\"><span>Best score</span><strong id=\"record-score\">0</strong></div><div class=\"record\"><span>Largest planet</span><strong id=\"record-planet\">—</strong></div><div class=\"record\"><span>Merges completed</span><strong id=\"record-merges\">0</strong></div><div class=\"record\"><span>Games started</span><strong id=\"record-games\">1</strong></div><button class=\"secondary\" id=\"share\">Share achievements & game</button><p class=\"fine\">Sharing opens Telegram’s recipient picker. You choose who receives it.</p></section>\n<footer>Made for a quick break. Stay for a good move.</footer></main>\n<dialog id=\"help-dialog\"><button class=\"icon close\" id=\"close-help\" aria-label=\"Close help\">×</button><h2>Make a bigger universe.</h2><p>Tap one of the five lanes or cells. Your next planet falls into it. Touching planets with the same number merge into the next number.</p><p>Merges can start a chain reaction. The more matches in a chain, the more points you earn. Keep room at the top!</p><h3>Boosters & Missions</h3><p>You earn free undos and shuffles as you clear orbital milestones and daily check-ins. Paid boosters are optional and keep your high score run alive.</p><h3>A fair little game</h3><p>There are no cash prizes or tokens. New games are always free. Daily Challenge mode is identical for all players worldwide with zero paid boosters.</p><h3>Your data</h3><p>Practice progress stays in this browser. In Telegram, identity is verified on the server before purchases. Payment records and paid boosters are kept to deliver purchases and resolve support requests.</p><p>Payment help: /paysupport in the game bot.</p></dialog><noscript><p>This puzzle needs JavaScript to run. Enable JavaScript to play.</p></noscript><script type=\"module\" src=\"./app.js\"></script></body></html>","type":"text/html; charset=utf-8"},"/style.css":{"body":":root{--blue:oklch(0.52 0.20 260);--ink:#142144;--muted:#536079;--paper:#f3f6fc;--line:#dce3ee;--navy:#111f3c;--white:#fff;font-family:'Segoe UI',sans-serif;color:var(--ink);background:var(--paper);font-synthesis:none}\n[data-theme=\"cyber\"]{--blue:#00f0ff;--navy:#0d1117;--paper:#0a0c10;--line:#21262d;--ink:#f0f6fc;--muted:#8b949e}\n[data-theme=\"solar\"]{--blue:#e65c00;--navy:#1a1005;--paper:#fbf8f3;--line:#ebdccb;--ink:#3d2406;--muted:#7d5c38}\n*{box-sizing:border-box}body{margin:0;min-height:100dvh;display:flex;justify-content:center;align-items:flex-start;gap:90px;padding:42px 24px}\nbutton{font:inherit;cursor:pointer;touch-action:manipulation;border:0;transition:transform 140ms ease-out,opacity 140ms ease-out}\nbutton:active{transform:translateY(1px)}button:focus-visible{outline:3px solid #12836a;outline-offset:4px}\nbutton:disabled{cursor:default;background:#e2e8f0!important;color:#475569!important;transform:none}\n.intro{width:320px;padding-top:80px}.orbit-mark{display:block;font-size:68px;color:var(--blue);line-height:1}\n.intro h1{font-family:'Trebuchet MS',sans-serif;font-size:54px;line-height:1.08;letter-spacing:-.035em;margin:24px 0}\n.intro>p{font-size:18px;line-height:1.6;color:var(--muted)}.rule{display:flex;gap:18px;align-items:center;margin:24px 0}\n.rule>span{border:1px solid #c2cde0;border-radius:50%;width:30px;height:30px;display:grid;place-items:center;color:var(--blue);font-weight:700}\n.rule p{margin:0;font-size:16px;line-height:1.6}.rule strong{font-weight:400;font-size:14px;color:var(--muted)}.intro .aside-note{font-size:14px;margin-top:44px}\n.app{width:440px;background:white;border:1px solid var(--line);border-radius:28px;padding:24px;box-shadow:0 16px 64px #24344f0c;overflow:hidden;position:relative}\n[data-theme=\"cyber\"] .app{background:#161b22;border-color:#30363d}\n[data-theme=\"solar\"] .app{background:#fffdfa;border-color:#e4cfb8}\nheader{display:flex;align-items:center;justify-content:space-between}\n.header-actions{display:flex;gap:8px;align-items:center}\n.brand{display:flex;align-items:center;gap:10px;font-family:'Trebuchet MS',sans-serif;font-size:23px;font-weight:700;letter-spacing:-.04em}\n.brand>span{font-size:38px;color:var(--blue)}.brand small{display:block;font-family:'Segoe UI',sans-serif;font-size:10px;color:var(--muted);font-weight:400;letter-spacing:0;margin-top:3px}\n.icon{width:34px;height:34px;border:1px solid var(--line);border-radius:50%;background:#fff;color:var(--ink);font-weight:600;display:grid;place-items:center}\n[data-theme=\"cyber\"] .icon{background:#21262d;border-color:#30363d;color:#f0f6fc}\nnav{display:flex;border-bottom:1px solid var(--line);margin:24px 0 22px}\n.tab{flex:1;padding:12px 4px;background:transparent;color:var(--muted);font-size:14px;font-weight:600;border-bottom:3px solid transparent}\n.tab.selected{color:var(--blue);border-bottom-color:var(--blue)}\n.scoreline{display:flex;justify-content:space-between;align-items:center;margin:0 2px 18px}\n.label{display:block;color:var(--muted);font-size:10px;font-weight:700;letter-spacing:.09em}\n.scoreline strong{display:block;font-family:'Trebuchet MS',sans-serif;font-size:38px;letter-spacing:-.03em;font-variant-numeric:tabular-nums;margin-top:3px}\n.best{text-align:right}.best strong{font-size:23px;color:var(--muted)}\n.mission{display:flex;align-items:center;gap:8px;font-size:11px;background:#eef3ff;padding:12px 10px;border-radius:10px;margin-bottom:14px;color:#28458b;transition:background 200ms ease}\n[data-theme=\"cyber\"] .mission{background:#1f2937;color:#60a5fa}\n[data-theme=\"solar\"] .mission{background:#fdf2e9;color:#b45309}\n.mission>span:first-child{font-size:17px}.mission>div{flex:1}.mission>span:last-child{font-weight:700;font-variant-numeric:tabular-nums}\n.game-wrap{background:var(--navy);border-radius:18px;padding:14px 12px 9px;color:#c4cfe3;position:relative}\n.queue{height:48px;display:flex;align-items:center;gap:10px;font-size:11px;padding:0 3px 12px}\n.free-label{margin-left:auto;font-size:9px;letter-spacing:.06em;color:#a8bce0}.following{font-size:10px}\n.planet{border-radius:50%;display:inline-grid;place-items:center;font-family:'Trebuchet MS',sans-serif;font-weight:700;font-size:21px;width:44px;height:44px;flex-shrink:0;box-shadow:inset -4px -5px 0 #00000018,inset 2px 2px 0 #ffffff45;color:#10203b;position:relative;user-select:none}\n.queue .planet{width:34px;height:34px;font-size:17px}.queue .small{width:24px;height:24px;font-size:12px}\n.l1{background:#92c7ff}.l2{background:#71ddcf}.l3{background:#ffc877}.l4{background:#ff9ba9}.l5{background:#c7b4ff}\n.l6{background:#d2e879;box-shadow:0 0 10px #d2e87980,inset -4px -5px 0 #00000018,inset 2px 2px 0 #ffffff50}\n.l7{background:#81e2fa;box-shadow:0 0 14px #81e2fa90,inset -4px -5px 0 #00000018,inset 2px 2px 0 #ffffff50}\n.l8{background:#ffbd85;box-shadow:0 0 18px #ffbd85a0,inset -4px -5px 0 #00000018,inset 2px 2px 0 #ffffff50}\n.l9{background:#f4e79a;box-shadow:0 0 22px #f4e79ac0,inset -4px -5px 0 #00000018,inset 2px 2px 0 #ffffff50;animation:pulse-star 2s infinite alternate ease-in-out}\n.l10{background:#ffffff;box-shadow:0 0 28px #ffffffdd,0 0 45px var(--blue),inset -4px -5px 0 #00000020,inset 2px 2px 0 #ffffff70;animation:pulse-star 1.4s infinite alternate ease-in-out}\n@keyframes pulse-star{from{filter:drop-shadow(0 0 4px gold)}to{filter:drop-shadow(0 0 12px #ff4571)}}\n.board{display:grid;grid-template-columns:repeat(5,1fr);grid-template-rows:repeat(6,minmax(0,1fr));gap:6px;background:#1c2e50;border:1px solid #344569;border-radius:10px;padding:7px;aspect-ratio:5/6;position:relative}\n.cell{min-width:0;border:1px solid #35456799;border-radius:8px;display:grid;place-items:center;background:#172846;overflow:hidden;position:relative}\n.cell .planet{width:86%;height:auto;aspect-ratio:1;max-height:94%;max-width:94%;font-size:clamp(17px,4vw,23px)}\n.cell.filled .planet{animation:arrive 180ms ease-out}\n.cell.ghost{background:#1f3964;outline:2px dashed #92c7ff80;outline-offset:-3px}\n.cell.ghost::after{content:'';width:50%;height:50%;border-radius:50%;background:#92c7ff40;display:block}\n.planet.pop{animation:merge-pop 280ms cubic-bezier(0.175,0.885,0.32,1.275)}\n@keyframes merge-pop{0%{transform:scale(0.5);opacity:0.6}50%{transform:scale(1.28)}100%{transform:scale(1);opacity:1}}\n.score-popup{position:absolute;pointer-events:none;font-family:'Trebuchet MS',sans-serif;font-weight:800;font-size:17px;color:#ffe600;text-shadow:0 2px 6px #000000cc;z-index:15;animation:float-up 650ms ease-out forwards}\n@keyframes float-up{0%{transform:translateY(0) scale(0.85);opacity:1}100%{transform:translateY(-34px) scale(1.15);opacity:0}}\n.lane-buttons{display:grid;grid-template-columns:repeat(5,1fr);gap:6px;padding:7px 8px 0}\n.lane{height:44px;color:#b9ccef;background:#293e65;border-radius:7px;font-size:18px;display:grid;place-items:center}\n.lane.active-lane{background:#3e5d95;color:#fff}\n.board-tip{text-align:center;font-size:10px;margin:11px 0 2px;color:#bbcae2}\n.tools{display:flex;gap:9px;margin-top:14px}\n.secondary,.primary{min-height:44px;padding:11px 15px;border-radius:11px;font-weight:600;font-size:13px}\n.secondary{background:#f1f4fa;color:var(--ink);border:1px solid var(--line)}\n[data-theme=\"cyber\"] .secondary{background:#21262d;color:#f0f6fc;border-color:#30363d}\n[data-theme=\"solar\"] .secondary{background:#f8f2e9;color:#3d2406;border-color:#e4cfb8}\n.primary{background:var(--blue);color:white}\n[data-theme=\"cyber\"] .primary{color:#0d1117;font-weight:700}\n.tools button{flex:1}.tools span{font-weight:400;font-size:10px;margin-left:5px;color:var(--muted)}\n.status{font-size:12px;line-height:1.5;min-height:22px;margin:8px 0;color:#385189}\n[data-theme=\"cyber\"] .status{color:#58a6ff}\n.collection{border-top:1px solid var(--line);padding:17px 0 2px}.collection strong{font-size:13px}\n.collection span:not(.planet):not(.connector){display:block;font-size:11px;color:var(--muted);margin-top:4px}\n.discovery{display:flex;gap:15px;align-items:center;margin-top:15px}.connector{color:#7b89a3}\nh2{font-family:'Trebuchet MS',sans-serif;font-size:25px;letter-spacing:-.025em;line-height:1.2;margin:20px 0 12px}\n.muted{color:var(--muted);line-height:1.6;font-size:14px}\n.notice{font-size:12px;border:1px solid var(--line);background:#f4f7fc;padding:13px;border-radius:10px;margin:22px 0}\n[data-theme=\"cyber\"] .notice{background:#161b22;border-color:#30363d;color:#8b949e}\n.product{display:flex;align-items:center;gap:12px;padding:20px 0;border-bottom:1px solid var(--line)}\n.product-symbol{font-size:29px;color:var(--blue);width:30px;display:grid;place-items:center}\n.product div{flex:1}.product h3{font-size:15px;margin:0 0 4px}\n.product p{font-size:12px;line-height:1.5;margin:0;color:var(--muted);max-width:185px}\n.product .badge{display:inline-block;font-size:9px;padding:2px 6px;border-radius:5px;background:#e2e8f0;color:#334155;margin-left:6px;font-weight:600}\n.badge.deal{background:#dcfce7;color:#15803d}\n.buy{white-space:nowrap}\n.fine{font-size:11px;line-height:1.7;color:var(--muted);margin:20px 0}\n.record{display:flex;justify-content:space-between;padding:20px 0;border-bottom:1px solid var(--line);font-size:14px}\n.record strong{font-size:24px;color:var(--blue)}\n.theme-select{display:flex;gap:8px;margin-top:12px}\n.theme-btn{flex:1;padding:8px 10px;font-size:12px;border-radius:8px;background:#f1f4fa;border:1px solid var(--line);color:var(--ink)}\n.theme-btn.active{border-color:var(--blue);font-weight:700;color:var(--blue);background:#eef3ff}\n#share{width:100%;margin-top:20px}\n.over{padding:0 0 18px}.over button{margin:4px 2px}.over p{font-size:13px;color:var(--muted)}\nfooter{font-size:10px;color:var(--muted);text-align:center;margin:24px 0 2px}\ndialog{width:min(90vw,440px);border:1px solid var(--line);border-radius:20px;color:var(--ink);padding:26px;background:white}\n[data-theme=\"cyber\"] dialog{background:#161b22;border-color:#30363d;color:#f0f6fc}\ndialog::backdrop{background:#10203b80}dialog p{font-size:14px;line-height:1.7;color:var(--muted)}dialog h3{font-size:16px}\n.close{float:right}[hidden]{display:none!important}\n@keyframes arrive{from{transform:scale(.95);opacity:.65}to{transform:scale(1);opacity:1}}\n@media(hover:hover){button:not(:disabled):hover{opacity:.85}.lane:not(:disabled):hover{background:#3d588c}}\n@media(max-width:850px){body{gap:30px}.intro{width:250px}.intro h1{font-size:42px}}\n@media(max-width:700px){body{padding:0;display:block;background:white}.intro{display:none}\n.app{width:100%;max-width:460px;margin:auto;border:0;border-radius:0;padding:max(18px,env(safe-area-inset-top)) 18px max(18px,env(safe-area-inset-bottom));box-shadow:none}\n.board{max-height:440px}nav{margin-top:18px}.scoreline{margin-bottom:14px}.scoreline strong{font-size:34px}.best strong{font-size:23px}\n.mission{margin-bottom:12px}.collection{padding-top:13px}footer{margin-top:18px}}\n@media(prefers-reduced-motion:reduce){.cell.filled .planet,.planet.pop{animation:none}button{transition:opacity 100ms ease-out}button:active{transform:none}}\n","type":"text/css; charset=utf-8"},"/app.js":{"body":"import {W,H,newGame,nextLevel,available,targetRow,drop,undo,rescue,shuffle,dailySeed} from './engine.js';\nimport {completedReward,showRewarded,completedMonetagReward,showMonetagRewarded} from './ads.js';\n\nconst $=s=>document.querySelector(s),tg=window.Telegram?.WebApp;\nconst STORAGE='orbit-merge-v1';\nlet stored;try{stored=JSON.parse(localStorage.getItem(STORAGE)||'null');}catch{}\n\nclass SoundFX {\n constructor(){\n  this.ctx=null;\n  this.muted=localStorage.getItem('orbit-sound-muted')==='true';\n }\n init(){\n  if(!this.ctx&&(window.AudioContext||window.webkitAudioContext)){\n   this.ctx=new(window.AudioContext||window.webkitAudioContext)();\n  }\n  if(this.ctx&&this.ctx.state==='suspended')this.ctx.resume();\n }\n toggle(){\n  this.muted=!this.muted;\n  localStorage.setItem('orbit-sound-muted',String(this.muted));\n  return !this.muted;\n }\n tone(freq,type='sine',dur=0.15,vol=0.12){\n  if(this.muted)return;\n  try{\n   this.init();\n   if(!this.ctx)return;\n   const osc=this.ctx.createOscillator(),g=this.ctx.createGain();\n   osc.type=type;\n   osc.frequency.setValueAtTime(freq,this.ctx.currentTime);\n   g.gain.setValueAtTime(vol,this.ctx.currentTime);\n   g.gain.exponentialRampToValueAtTime(0.0001,this.ctx.currentTime+dur);\n   osc.connect(g);g.connect(this.ctx.destination);\n   osc.start();osc.stop(this.ctx.currentTime+dur);\n  }catch{}\n }\n drop(){this.tone(170,'triangle',0.12,0.14);}\n merge(level,chain=1){\n  const notes=[261.63,293.66,329.63,392.00,440.00,523.25,587.33,659.25,783.99,880.00,1046.50];\n  const base=notes[Math.min(Math.max(0,level-1),notes.length-1)];\n  const mult=1+(chain-1)*0.15;\n  this.tone(base*mult,'sine',0.24,0.18);\n  if(level>=5)setTimeout(()=>this.tone(base*1.5*mult,'triangle',0.26,0.12),55);\n }\n undo(){this.tone(220,'sine',0.12,0.1);}\n shuffle(){\n  [220,277.18,329.63,440].forEach((f,i)=>setTimeout(()=>this.tone(f,'sine',0.15,0.1),i*40));\n }\n gameOver(){\n  this.tone(220,'sawtooth',0.3,0.1);\n  setTimeout(()=>this.tone(165,'sine',0.4,0.1),140);\n }\n fanfare(){\n  [523.25,659.25,783.99,1046.50].forEach((f,i)=>setTimeout(()=>this.tone(f,'sine',0.22,0.15),i*75));\n }\n}\n\nconst sfx=new SoundFX();\n$('#sound').textContent=sfx.muted?'🔇':'🔊';\n$('#sound').addEventListener('click',()=>{\n const on=sfx.toggle();\n $('#sound').textContent=on?'🔊':'🔇';\n if(on)sfx.drop();\n});\n\nlet game=stored?.game&&Array.isArray(stored.game.board)&&stored.game.board.length===W*H?stored.game:newGame();\nlet records=stored?.records||{best:0,largest:0,games:1,merges:0,missionIdx:0,theme:'default'};\nlet freeUndo=stored?.freeUndo??1,freeShuffle=stored?.freeShuffle??1,account=null,busy=false,config={},pending=stored?.pending||null,adAvailable=false;\nlet hoveredLane=null,lastDropChain=0,lastMergedPos=null,lastScoredPoints=0;\n\nif(records.theme&&records.theme!=='default'){\n document.documentElement.setAttribute('data-theme',records.theme);\n document.querySelectorAll('.theme-btn').forEach(b=>b.classList.toggle('active',b.dataset.setTheme===records.theme));\n}\n\nconst MISSIONS=[\n {title:'Mission 1: Discover a 32 Planet',target:32,check:(g)=>Math.max(0,...g.board)>=5,progress:(g)=>`${Math.max(0,...g.board)?2**Math.min(5,Math.max(...g.board)):0} / 32`,reward:'+1 Free Undo',grant:()=>{freeUndo++;}},\n {title:'Mission 2: Trigger a 2-Step Cascade',target:2,check:(g,c)=>c>=2,progress:(g,c)=>`${Math.min(2,c||0)} / 2`,reward:'+1 Free Shuffle',grant:()=>{freeShuffle++;}},\n {title:'Mission 3: Score 1,000 in one orbit',target:1000,check:(g)=>g.score>=1000,progress:(g)=>`${Math.min(1000,g.score)} / 1000`,reward:'+1 Free Undo',grant:()=>{freeUndo++;}},\n {title:'Mission 4: Discover a 128 Planet',target:128,check:(g)=>Math.max(0,...g.board)>=7,progress:(g)=>`${Math.max(0,...g.board)?2**Math.min(7,Math.max(...g.board)):0} / 128`,reward:'+1 Free Rescue',grant:()=>{if(account)account.rescues++;}},\n {title:'Mission 5: Reach 3,000 High Score',target:3000,check:(g)=>g.score>=3000,progress:(g)=>`${Math.min(3000,g.score)} / 3000`,reward:'+1 Free Shuffle',grant:()=>{freeShuffle++;}},\n {title:'Mastery: Forge a 2048 Cosmic Star',target:2048,check:(g)=>Math.max(0,...g.board)>=11,progress:(g)=>`${Math.max(0,...g.board)?2**Math.min(11,Math.max(...g.board)):0} / 2048`,reward:'Supernova Master',grant:()=>{}}\n];\n\nconst dailyDate=new Date().toISOString().slice(0,10);\nconst dailyStorage='orbit-merge-daily-'+dailyDate;\nlet dailyMode=false,regularGame;\nlet dailyGame=newGame(dailySeed(dailyDate));\ntry{\n const savedDaily=JSON.parse(localStorage.getItem('orbit-merge-daily')||'null');\n if(savedDaily?.key===dailyStorage&&savedDaily.game?.board?.length===W*H)dailyGame=savedDaily.game;\n}catch{}\n\nfunction checkMissions(){\n if(dailyMode)return;\n const idx=records.missionIdx||0;\n if(idx>=MISSIONS.length)return;\n const m=MISSIONS[idx];\n if(m.check(game,lastDropChain)){\n  records.missionIdx=idx+1;\n  m.grant();\n  sfx.fanfare();\n  try{tg?.HapticFeedback?.notificationOccurred('success');}catch{}\n  $('#status').textContent=`🎉 ${m.title} cleared! Reward: ${m.reward}!`;\n  save();\n }\n}\n\nfunction toggleDaily(){\n if(busy||pending)return;\n if(dailyMode){dailyGame=game;game=regularGame;}\n else{regularGame=game;game=dailyGame;}\n dailyMode=!dailyMode;\n $('#daily').textContent=dailyMode?'Back to free play':'Daily challenge';\n $('#daily-share').hidden=!dailyMode;\n $('#daily-info').textContent=dailyMode?'Same puzzle for everyone. No boosters. New puzzle at midnight UTC.':'';\n $('#status').textContent='';\n render();\n}\n\nfunction save(){\n try{\n  if(dailyMode){localStorage.setItem('orbit-merge-daily',JSON.stringify({key:dailyStorage,game}));return true;}\n  localStorage.setItem(STORAGE,JSON.stringify({game,records,freeUndo,freeShuffle,pending}));\n  return true;\n }catch{\n  $('#status').textContent='Browser storage is unavailable. Progress lasts for this session.';\n  return false;\n }\n}\n\nfunction planet(level,pop=false){\n const el=document.createElement('span');\n el.className=`planet l${Math.min(level,10)}${pop?' pop':''}`;\n el.textContent=(2**level).toLocaleString();\n return el;\n}\n\nfunction render(){\n $('#score').textContent=game.score.toLocaleString();\n if(!dailyMode){\n  records.best=Math.max(records.best,game.score);\n  records.largest=Math.max(records.largest,...game.board);\n }\n $('#best').textContent=records.best.toLocaleString();\n\n const curMission=MISSIONS[Math.min(records.missionIdx||0,MISSIONS.length-1)];\n $('#mission').textContent=records.missionIdx>=MISSIONS.length?'All missions complete! Galaxy Legend.':curMission.title;\n $('#progress').textContent=records.missionIdx>=MISSIONS.length?'★ ★ ★':curMission.progress(game,lastDropChain);\n\n const ghostRow=hoveredLane!==null?targetRow(game,hoveredLane):-1;\n const board=$('#board');\n board.replaceChildren();\n\n for(let r=0;r<H;r++){\n  for(let c=0;c<W;c++){\n   const pos=r*W+c;\n   const n=game.board[pos];\n   const cell=document.createElement('div');\n   const isGhost=hoveredLane===c&&r===ghostRow&&!n;\n   cell.className=`cell${n?' filled':''}${isGhost?' ghost':''}`;\n   cell.setAttribute('aria-label',`Row ${r+1}, lane ${c+1}: ${n?2**n:'empty'}`);\n   if(n){\n    const isPop=lastMergedPos===pos;\n    cell.append(planet(n,isPop));\n   }\n   cell.addEventListener('mouseenter',()=>{hoveredLane=c;renderGhost();});\n   cell.addEventListener('mouseleave',()=>{hoveredLane=null;renderGhost();});\n   cell.addEventListener('click',()=>play(c));\n   board.append(cell);\n  }\n }\n\n const lanes=$('#lanes');\n lanes.replaceChildren();\n for(let c=0;c<W;c++){\n  const b=document.createElement('button');\n  b.className=`lane${hoveredLane===c?' active-lane':''}`;\n  b.textContent='↓';\n  b.ariaLabel=`Drop in lane ${c+1}`;\n  b.disabled=!available(game,c)||game.over||busy;\n  b.addEventListener('mouseenter',()=>{hoveredLane=c;renderGhost();});\n  b.addEventListener('mouseleave',()=>{hoveredLane=null;renderGhost();});\n  b.addEventListener('click',()=>play(c));\n  lanes.append(b);\n }\n\n for(const id of ['undo','shuffle','new','restart','rescue','ad'])document.getElementById(id).hidden=dailyMode;\n document.getElementById('over-copy').textContent=dailyMode?'Share your score or return to free play.':'A new universe is always free.';\n\n for(const [id,offset] of [['next',0],['after',1]]){\n  const n=nextLevel(game,offset),el=$('#'+id);\n  el.className=`planet l${n}${offset?' small':''}`;el.textContent=2**n;\n }\n\n $('#undo-count').textContent=freeUndo?'1 free':`${account?.undos||0} left`;\n $('#undo').disabled=!game.history.length||busy;\n\n $('#shuffle-count').textContent=freeShuffle?'1 free':`${account?.shuffles||0} left`;\n $('#shuffle').disabled=game.over||busy||game.board.filter(Boolean).length<2;\n\n $('#gameover').hidden=!game.over;\n $('#rescue').textContent=`Use a rescue (${account?.rescues||0} left)`;\n $('#rescue').disabled=busy;\n $('#ad').disabled=busy||!adAvailable||!!game.adUsed;\n $('#ad').textContent=game.adUsed?'Ad rescue used this orbit':adAvailable?'Watch an ad · rescue this orbit':'Rewarded ad unavailable';\n\n $('#record-score').textContent=records.best.toLocaleString();\n $('#record-planet').textContent=records.largest?2**records.largest:'—';\n $('#record-merges').textContent=(records.merges||0).toLocaleString();\n $('#record-games').textContent=records.games;\n\n updateDailySupplyUI();\n save();\n}\n\nfunction renderGhost(){\n const ghostRow=hoveredLane!==null?targetRow(game,hoveredLane):-1;\n document.querySelectorAll('#board .cell').forEach((cell,idx)=>{\n  const c=idx%W,r=Math.floor(idx/W);\n  const isGhost=hoveredLane===c&&r===ghostRow&&!game.board[idx];\n  cell.classList.toggle('ghost',isGhost);\n });\n document.querySelectorAll('#lanes .lane').forEach((btn,idx)=>{\n  btn.classList.toggle('active-lane',hoveredLane===idx);\n });\n}\n\nfunction spawnScorePopup(pos,points,chain){\n const board=$('#board');\n if(!board)return;\n const cell=board.children[pos];\n if(!cell)return;\n const popup=document.createElement('span');\n popup.className='score-popup';\n popup.textContent=`+${points}${chain>1?' x'+chain:''}`;\n cell.append(popup);\n setTimeout(()=>popup.remove(),650);\n}\n\nfunction play(c){\n if(busy)return;\n if(pending){$('#status').textContent='Finish your pending booster by pressing its button again.';return;}\n const prevScore=game.score;\n const result=drop(game,c);\n if(!result){$('#status').textContent='That lane is full. Try another one.';return;}\n\n sfx.drop();\n lastDropChain=result.chain||0;\n lastMergedPos=result.at;\n lastScoredPoints=game.score-prevScore;\n\n if(result.chain>0){\n  records.merges=(records.merges||0)+result.chain;\n  sfx.merge(result.level||2,result.chain);\n  spawnScorePopup(result.at,lastScoredPoints,result.chain);\n }\n\n $('#status').textContent=result.chain>1?`${result.chain}-step cascade! Nicely calculated.`:result.chain?'Planets merged. Space expands.':'';\n try{tg?.HapticFeedback?.impactOccurred(result.chain>1?'medium':'light');}catch{}\n\n checkMissions();\n render();\n\n if(game.over){\n  sfx.gameOver();\n  try{tg?.HapticFeedback?.notificationOccurred('warning');}catch{}\n }\n}\n\nfunction start(){\n if(dailyMode||busy)return;\n if(pending){$('#status').textContent='Finish your pending booster first. Reopen the game to retry safely.';return;}\n game=newGame();freeUndo=1;freeShuffle=1;records.games++;\n $('#status').textContent='A fresh orbit. Your first undo & shuffle are free.';\n sfx.drop();\n render();\n}\n\nasync function api(path,body){\n const r=await fetch('/api/'+path,{method:'POST',headers:{'content-type':'application/json','x-telegram-init-data':tg?.initData||''},body:JSON.stringify(body||{})});\n let result;try{result=await r.json();}catch{throw new Error('Purchases are unavailable on this preview.');}\n if(!r.ok){const e=new Error(result.error||'Please try again.');e.rejected=true;throw e;}\n return result;\n}\n\nasync function spend(kind){\n if(pending&&pending.kind!==kind)throw new Error('Finish the other pending booster first.');\n if(!pending)pending={kind,request_id:crypto.randomUUID(),game:structuredClone(game)};\n if(!save()){pending=null;throw new Error('Paid boosters need browser storage to safely recover interrupted requests.');}\n try{\n  account=await api('consume',{kind,request_id:pending.request_id});\n  game=pending.game;\n  if(kind==='undos')undo(game);\n  else if(kind==='shuffles')shuffle(game);\n  else rescue(game);\n  pending=null;save();\n }catch(e){if(e.rejected){pending=null;save();}throw e;}\n}\n\nasync function refreshAccount(){\n account=await api('account');\n $('#balance').textContent=`Your boosters: ${account.undos||0} undos · ${account.shuffles||0} shuffles · ${account.rescues||0} rescues`;\n render();\n}\n\n$('#undo').addEventListener('click',async()=>{\n if(!game.history.length||busy)return;\n busy=true;render();\n try{\n  if(freeUndo){freeUndo--;undo(game);}\n  else await spend('undos');\n  sfx.undo();\n  $('#status').textContent='Last drop undone.';\n }catch(e){\n  $('#status').textContent=e.message+(pending?' Press Undo to retry safely.':'');\n }finally{busy=false;render();}\n});\n\n$('#shuffle').addEventListener('click',async()=>{\n if(game.over||busy||game.board.filter(Boolean).length<2)return;\n busy=true;render();\n try{\n  if(freeShuffle){freeShuffle--;shuffle(game);}\n  else await spend('shuffles');\n  sfx.shuffle();\n  try{tg?.HapticFeedback?.impactOccurred('medium');}catch{}\n  $('#status').textContent='Cosmic shuffle! Planets rearranged.';\n }catch(e){\n  $('#status').textContent=e.message;\n }finally{busy=false;render();}\n});\n\n$('#rescue').addEventListener('click',async()=>{\n if(!game.over||busy)return;\n busy=true;render();\n try{\n  await spend('rescues');\n  sfx.fanfare();\n  $('#status').textContent='Room to breathe. Keep your orbit going.';\n }catch(e){$('#status').textContent=e.message;}finally{busy=false;render();}\n});\n\n$('#new').addEventListener('click',()=>{\n if(game.drops&&!game.over){if(!confirm('Start a new orbit? Current board will reset.'))return;}\n start();\n});\n$('#restart').addEventListener('click',start);\n\ndocument.querySelectorAll('[data-view]').forEach(b=>b.addEventListener('click',()=>{\n document.querySelectorAll('.view').forEach(v=>v.hidden=v.id!==b.dataset.view);\n document.querySelectorAll('.tab').forEach(t=>{\n  t.classList.toggle('selected',t===b);\n  if(t===b)t.setAttribute('aria-current','page');else t.removeAttribute('aria-current');\n });\n}));\n\n$('#help').addEventListener('click',()=>$('#help-dialog').showModal());\n$('#close-help').addEventListener('click',()=>$('#help-dialog').close());\n\ndocument.querySelectorAll('[data-set-theme]').forEach(btn=>{\n btn.addEventListener('click',()=>{\n  const theme=btn.dataset.setTheme;\n  records.theme=theme;\n  if(theme==='default')document.documentElement.removeAttribute('data-theme');\n  else document.documentElement.setAttribute('data-theme',theme);\n  document.querySelectorAll('.theme-btn').forEach(b=>b.classList.toggle('active',b===btn));\n  save();\n });\n});\n\nfunction updateDailySupplyUI(){\n const btn=$('#daily-supply-btn'),desc=$('#daily-supply-desc');\n if(!btn||!desc)return;\n const claimed=records.lastDailySupply===dailyDate;\n if(claimed){\n  btn.textContent='Claimed';\n  btn.disabled=true;\n  desc.textContent='Daily supply opened for today. Come back tomorrow!';\n }else{\n  btn.textContent='Claim';\n  btn.disabled=false;\n  desc.textContent=adAvailable?'Watch sponsor ad · claim 1 free booster!':'Claim 1 free mystery booster today!';\n }\n}\n\n$('#daily-supply-btn').addEventListener('click',async()=>{\n if(busy||records.lastDailySupply===dailyDate)return;\n busy=true;\n try{\n  let success=false;\n  if(adAvailable){\n   const res=config.monetag?completedMonetagReward(await showMonetagRewarded(config.monetag)):completedReward(await showRewarded(config.adsBlockId));\n   success=!!res;\n  }else{\n   success=true;\n  }\n  if(success){\n   const grantUndo=Math.random()<0.5;\n   if(grantUndo)freeUndo++;else freeShuffle++;\n   records.lastDailySupply=dailyDate;\n   sfx.fanfare();\n   try{tg?.HapticFeedback?.notificationOccurred('success');}catch{}\n   $('#shop-status').textContent=`🎁 Mystery reward unlocked: +1 Free ${grantUndo?'Undo':'Shuffle'} added!`;\n  }else{\n   $('#shop-status').textContent='Ad not completed. Mystery booster was not awarded.';\n  }\n }catch{\n  $('#shop-status').textContent='Sponsor supply temporarily unavailable. Try again shortly.';\n }finally{\n  busy=false;\n  render();\n }\n});\n\n$('#share').addEventListener('click',async()=>{\n const url=config.botUsername?`https://t.me/${config.botUsername}?startapp=play`:location.origin;\n const maxP=records.largest?2**records.largest:'32';\n const text=`🪐 Orbit Merge Record!\\n🏆 Best Score: ${records.best.toLocaleString()}\\n⭐ Highest Planet: ${maxP}\\n🎮 Merges: ${(records.merges||0).toLocaleString()}\\nCan you build a bigger universe? Play free:`;\n if(tg?.initData)tg.openTelegramLink(`https://t.me/share/url?url=${encodeURIComponent(url)}&text=${encodeURIComponent(text)}`);\n else if(navigator.share){try{await navigator.share({title:'Orbit Merge',text,url});}catch{}}\n else{try{await navigator.clipboard.writeText(text+' '+url);$('#share').textContent='Record summary copied!';}catch{$('#share').textContent='Copy from address bar';}}\n});\n\nconst purchaseStorage='orbit-merge-pending-order';\nlet pendingPurchase;try{pendingPurchase=localStorage.getItem(purchaseStorage);}catch{}\nfunction rememberPurchase(orderId){pendingPurchase=orderId;try{if(orderId)localStorage.setItem(purchaseStorage,orderId);else localStorage.removeItem(purchaseStorage);}catch{}}\n\nasync function checkPurchase(orderId,attempts=1){\n const status=$('#shop-status');\n for(let attempt=0;attempt<attempts;attempt++){\n  try{\n   if((await api('order',{orderId})).paid){\n    await refreshAccount();\n    if(pendingPurchase===orderId)rememberPurchase(null);\n    status.textContent='Purchase confirmed. Boosters added to your balance.';\n    return;\n   }\n  }catch{}\n  if(attempt+1<attempts)await new Promise(r=>setTimeout(r,1200));\n }\n status.textContent='Awaiting confirmation. Check status again or contact payment support with your Telegram receipt.';\n}\n\nconst buyButtons=[...document.querySelectorAll('[data-product]')];\n$('#check-purchase').addEventListener('click',()=>{\n if(pendingPurchase)checkPurchase(pendingPurchase);\n else refreshAccount().catch(e=>{$('#shop-status').textContent=e.message;});\n});\n\nfor(const button of buyButtons){\n button.addEventListener('click',async()=>{\n  if(busy)return;busy=true;buyButtons.forEach(b=>b.disabled=true);\n  const status=$('#shop-status');\n  const unlock=()=>{busy=false;buyButtons.forEach(b=>b.disabled=false);};\n  status.textContent='Opening Telegram Stars checkout…';\n  try{\n   const {url,orderId}=await api('invoice',{product:button.dataset.product});\n   tg.openInvoice(url,async res=>{\n    if(res==='paid'||res==='pending'){\n     rememberPurchase(orderId);\n     status.textContent='Checking payment confirmation…';\n     try{await checkPurchase(orderId,6);}finally{unlock();}\n    }else{\n     status.textContent=res==='cancelled'?'Purchase cancelled.':'Checkout did not complete.';\n     unlock();\n    }\n   });\n  }catch(e){status.textContent=e.message;unlock();}\n });\n}\n\nwindow.addEventListener('keydown',e=>{\n if($('#play').hidden||$('#help-dialog').open)return;\n if(/^[1-5]$/.test(e.key))play(Number(e.key)-1);\n if(e.key==='u'||e.key==='U')$('#undo').click();\n if(e.key==='s'||e.key==='S')$('#shuffle').click();\n});\n\ntry{tg?.ready();tg?.expand();tg?.setHeaderColor('#f3f6fc');tg?.setBackgroundColor('#f3f6fc');}catch{}\nrender();\n\ntry{const r=await fetch('/api/config');if(r.ok)config=await r.json();}catch{}\nif(config.payments&&tg?.initData){\n try{\n  await refreshAccount();\n  $('#commerce-status').textContent='Telegram Stars · Secure one-time purchases';\n  document.querySelectorAll('.buy').forEach(b=>b.disabled=false);\n  $('#mode').textContent='TELEGRAM';\n }catch(e){$('#commerce-status').textContent=e.message;}\n}\n\nif(pending&&account){\n busy=true;\n try{\n  await spend(pending.kind);\n  $('#status').textContent='Your interrupted booster was recovered.';\n }catch(e){$('#status').textContent=e.message;}finally{busy=false;render();}\n}\n\nadAvailable=!!((config.monetag||config.ads&&/^\\d+$/.test(config.adsBlockId||''))&&tg?.initData);\nrender();\n\n$('#ad').addEventListener('click',async()=>{\n if(dailyMode||!adAvailable||busy||!game.over||game.adUsed||pending)return;\n busy=true;render();\n try{\n  const completed=config.monetag?completedMonetagReward(await showMonetagRewarded(config.monetag)):completedReward(await showRewarded(config.adsBlockId));\n  if(completed){\n   rescue(game);game.adUsed=true;\n   sfx.fanfare();\n   $('#status').textContent='Ad completed. Your orbit has room again.';\n  }else $('#status').textContent='Ad not completed. No rescue was used.';\n }catch{$('#status').textContent='Ad skipped or unavailable. No rescue was used.';}finally{busy=false;render();}\n});\n\n$('#daily').addEventListener('click',toggleDaily);\n$('#daily-share').addEventListener('click',async()=>{\n const url='https://t.me/OrbitMergeAjayBot/play?startapp=daily';\n const msg=`Orbit Merge Daily · ${dailyDate}\\nScore: ${game.score}\\nSame puzzle for everyone. Zero boosters. Can you beat me?\\n${url}`;\n if(tg?.initData){\n  tg.openTelegramLink('https://t.me/share/url?url='+encodeURIComponent(url)+'&text='+encodeURIComponent(msg));\n }else{\n  try{await navigator.clipboard.writeText(msg);$('#status').textContent='Daily challenge link copied!';}catch{$('#status').textContent=url;}\n }\n});\n\nif(tg?.initDataUnsafe?.start_param==='daily'||new URLSearchParams(location.search).get('mode')==='daily')toggleDaily();\n","type":"text/javascript; charset=utf-8"},"/engine.js":{"body":"export const W=5,H=6;\nexport function dailySeed(date) {\n let seed = 2166136261;\n for (const character of date) seed = Math.imul(seed ^ character.charCodeAt(0), 16777619);\n return seed >>> 0;\n}\nexport function random(seed){let x=seed>>>0;return()=>{x=(Math.imul(1664525,x)+1013904223)>>>0;return x/4294967296;};}\nexport function newGame(seed=Date.now()){return {seed:seed>>>0,board:Array(W*H).fill(0),score:0,drops:0,merges:0,history:[],over:false};}\nexport function nextLevel(g,offset=0){const rng=random(g.seed);let n;for(let i=0;i<=g.drops+offset;i++)n=rng();return n<.6?1:n<.9?2:3;}\nexport function available(g,c){return Number.isInteger(c)&&c>=0&&c<W&&g.board[c]===0;}\nexport function targetRow(g,c){if(!available(g,c)||g.over)return -1;let r=H-1;while(r>=0&&g.board[r*W+c])r--;return r;}\nexport function drop(g,c){\n if(!available(g,c)||g.over)return false;\n g.history.push({board:[...g.board],score:g.score,drops:g.drops,merges:g.merges});if(g.history.length>20)g.history.shift();\n let r=H-1;while(g.board[r*W+c])r--;let at=r*W+c;g.board[at]=nextLevel(g);g.drops++;let chain=0;let scoredAt=at;\n while(true){const level=g.board[at],seen=new Set([at]),stack=[at];while(stack.length){const p=stack.pop(),x=p%W,y=Math.floor(p/W);for(const q of [x>0?p-1:-1,x<W-1?p+1:-1,y>0?p-W:-1,y<H-1?p+W:-1])if(q>=0&&g.board[q]===level&&!seen.has(q)){seen.add(q);stack.push(q);}}\n if(seen.size<2)break;\n for(const p of seen)g.board[p]=0;g.board[at]=level+1;chain++;g.merges+=seen.size-1;g.score+=(2**(level+1))*(seen.size-1)*chain;scoredAt=at;\n // Gravity preserves each column's order and tracks the surviving planet.\n for(let x=0;x<W;x++){const items=[];for(let y=H-1;y>=0;y--){const p=y*W+x;if(g.board[p])items.push({value:g.board[p],anchor:p===at});}for(let y=0;y<H;y++)g.board[y*W+x]=0;items.forEach((v,i)=>{const p=(H-1-i)*W+x;g.board[p]=v.value;if(v.anchor)at=p;});}\n }\n g.over=g.board.slice(0,W).every(Boolean);return {chain,at:scoredAt,level:g.board[scoredAt]};\n}\nexport function undo(g){const h=g.history.pop();if(!h)return false;Object.assign(g,h,{over:false});return true;}\nexport function rescue(g){if(!g.over)return false;for(let c=0;c<W;c++)g.board[c]=0;g.history=[];g.over=false;return true;}\nexport function shuffle(g){\n if(g.over)return false;\n const items=[];for(let i=0;i<g.board.length;i++){if(g.board[i])items.push(g.board[i]);}\n if(items.length<2)return false;\n g.history.push({board:[...g.board],score:g.score,drops:g.drops,merges:g.merges});if(g.history.length>20)g.history.shift();\n for(let i=items.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[items[i],items[j]]=[items[j],items[i]];}\n const cols=Array.from({length:W},()=>[]);\n items.forEach((v,i)=>cols[i%W].push(v));\n g.board.fill(0);\n for(let x=0;x<W;x++){for(let i=0;i<cols[x].length;i++){g.board[(H-1-i)*W+x]=cols[x][i];}}\n return true;\n}\n","type":"text/javascript; charset=utf-8"},"/ads.js":{"body":"let controllerPromise;\nlet monetagPromise;\nexport function completedMonetagReward(result) {\n return result?.reward_event_type === 'valued';\n}\n\nexport async function showMonetagRewarded({zone, scriptUrl}) {\n if (!/^\\d+$/.test(zone)) throw new Error('Invalid Monetag zone.');\n const source = new URL(scriptUrl);\n if (source.protocol !== 'https:') throw new Error('Monetag SDK requires HTTPS.');\n const functionName = 'show_' + zone;\n if (!monetagPromise) {\n  monetagPromise = new Promise((resolve, reject) => {\n   const script = document.createElement('script');\n   script.src = source.href;\n   script.dataset.zone = zone;\n   script.dataset.sdk = functionName;\n   const fail = message => {\n    clearTimeout(timer);\n    script.onload = script.onerror = null;\n    script.remove();\n    reject(new Error(message));\n   };\n   const timer = setTimeout(() => fail('Monetag SDK timed out.'), 6000);\n   script.onload = () => {\n    if (typeof window[functionName] !== 'function') {\n     fail('Monetag SDK unavailable.');\n     return;\n    }\n    clearTimeout(timer);\n    resolve(window[functionName]);\n   };\n   script.onerror = () => fail('Monetag SDK failed to load.');\n   document.head.append(script);\n  }).catch(error => {\n   monetagPromise = null;\n   throw error;\n  });\n }\n const show = await monetagPromise;\n return show({type: 'end', ymid: crypto.randomUUID(), requestVar: 'game_over_rescue', timeout: 10});\n}\n\nexport function completedReward(result){return result?.done===true&&result?.error===false;}\nexport async function showRewarded(blockId){\n if(!/^\\d+$/.test(blockId||''))throw new Error('Rewarded ads are not configured.');\n if(!controllerPromise)controllerPromise=(async()=>{if(!window.Adsgram)await new Promise((resolve,reject)=>{const script=document.createElement('script');script.src='https://sad.adsgram.ai/js/sad.min.js';script.onload=resolve;script.onerror=()=>reject(new Error('Ad service unavailable.'));document.head.append(script);});return window.Adsgram.init({blockId,debug:false});})();\n let controller;try{controller=await controllerPromise;}catch(e){controllerPromise=null;throw e;}return controller.show();\n}\n","type":"text/javascript; charset=utf-8"}});
